import os # Keep independent constitutive checks within the same CPU budget.
os.environ['OMP_NUM_THREADS']='1';os.environ['OPENBLAS_NUM_THREADS']='1' # Prevent concurrent native checks from oversubscribing numerical threads.
import json,subprocess,time,zipfile # Save actual native output and analytic comparison evidence.
from pathlib import Path # Resolve immutable verification artifacts.
import numpy as np # Implement an independent uniaxial return mapping and field comparisons.
from complex_rebar import OUT,CCX,parse_dat,sha,save # Reuse only I/O identities and the native text parser, not native constitutive integration.
def uniaxial_check(): # Compare actual finite-strain native steel to an independent small-elastic-strain kinematic hardening solution.
    directory=OUT/'verification/uniaxial';directory.mkdir(parents=True,exist_ok=True);E=200000.;H=1500.;fy=350.;L=20.;path=np.array([0.,.0005,.003,.008,.002,-.004,0.,.004]);xyz=np.array([[0,0,0],[L,0,0],[L,10,0],[0,10,0],[0,0,10],[L,0,10],[L,10,10],[0,10,10]],float) # Use one exactly uniform C3D8 stress state with unrestrained Poisson contraction.
    lines=['*HEADING','Independent uniaxial cyclic kinematic plasticity check','*NODE,NSET=ALL']+[f'{i+1},'+','.join(map(str,p)) for i,p in enumerate(xyz)]+['*ELEMENT,TYPE=C3D8,ELSET=STEEL','1,1,2,3,4,5,6,7,8','*NSET,NSET=DRIVE','2,3,6,7','*MATERIAL,NAME=STEEL','*ELASTIC',f'{E},0.3','*PLASTIC,HARDENING=KINEMATIC',f'{fy},0.',f'{fy+H*.05},.05','*SOLID SECTION,ELSET=STEEL,MATERIAL=STEEL','*BOUNDARY','1,1,3,0.','4,1,1,0.','4,3,3,0.','5,1,1,0.','8,1,1,0.'] # Remove rigid modes with minimal lateral pins and no imposed triaxial restraint.
    for strain in path[1:]: lines.extend(['*STEP,NLGEOM,INC=400','*STATIC','.25,1.,1.e-6,.25','*CONTROLS,PARAMETERS=TIME INCREMENTATION','20,40,99,80,60,6,,12','.25,.5,.75,.85,,,1.5','*CONTROLS,PARAMETERS=FIELD','1.e-7,1.e-3,,,1.e-7,1.e-6,1.e-5,1.e-8','*BOUNDARY',f'DRIVE,1,1,{strain*L:.15g}','*NODE PRINT,NSET=ALL,FREQUENCY=999999','U,RF','*EL PRINT,ELSET=STEEL,FREQUENCY=999999','S,SDV','*END STEP']) # Execute signed loading and unloading with actual native plastic history.
    inp=directory/'model.inp';inp.write_text('\n'.join(lines)+'\n');start=time.monotonic();process=subprocess.run([str(CCX),'model'],cwd=directory,capture_output=True,text=True,timeout=180);log=process.stdout+process.stderr;(directory/'solver.log').write_text(log) # Save the genuine native constitutive response.
    with zipfile.ZipFile(directory/'native_evidence.zip','w',zipfile.ZIP_DEFLATED) as archive: # Snapshot every native verification file immediately after completion.
        for p in directory.glob('model.*'): archive.write(p,p.name) # Preserve input and printed numerical evidence for independent checks.
        archive.write(directory/'solver.log','solver.log') # Keep status with the exact native data.
    frames=parse_dat(directory/'model.dat');plastic=0.;alpha=0.;accumulated=0.;rows=[] # Initialize a completely independent uniaxial constitutive state.
    for i,engineering in enumerate(path[1:],1): # Follow the exact same signed history using logarithmic total strain.
        strain=float(np.log1p(engineering));trial=E*(strain-plastic);shifted=trial-alpha;yield_function=abs(shifted)-fy # Compute the uniaxial kinematic-hardening trial state.
        if yield_function>0.: increment=yield_function/(E+H);direction=float(np.sign(shifted));plastic+=increment*direction;alpha+=H*increment*direction;accumulated+=increment # Apply the independent scalar return mapping.
        predicted=E*(strain-plastic);frame=frames[float(i)];stress=float(frame['stress'][:,2].mean());kappa=float(frame['sdv'][:,2].mean());rows.append({'step':i,'engineering_strain':engineering,'log_strain':strain,'native_cauchy_sxx_MPa':stress,'independent_uniaxial_stress_MPa':predicted,'stress_difference_over_yield':abs(stress-predicted)/fy,'native_peeq':kappa,'independent_accumulated_plastic_strain':accumulated,'peeq_difference':abs(kappa-accumulated)}) # Compare exact uniform native fields to the independent analytic approximation.
    maximum=max(r['stress_difference_over_yield'] for r in rows);plastic_error=max(r['peeq_difference'] for r in rows);status='PASS' if process.returncode==0 and 'Job finished' in log and '*ERROR' not in log and maximum<.01 and plastic_error<1.e-4 else 'HOLD';report={'status':status,'comparison_scope':'Actual finite-strain multiplicative native plasticity versus independent 1D kinematic return mapping in logarithmic strain. Small elastic strains permit a 1percent yield-normalized stress approximation threshold; this is not an exact proof of the native finite-strain formulation.','max_stress_difference_over_yield':maximum,'max_peeq_difference':plastic_error,'rows':rows,'seconds':time.monotonic()-start,'files':{p.name:sha(p) for p in directory.iterdir() if p.is_file() and p.name!='report.json'}};save(directory/'report.json',report);print(json.dumps({k:report[k] for k in ['status','max_stress_difference_over_yield','max_peeq_difference','seconds']}),flush=True);return report # Preserve observed agreement without silently relaxing the registered threshold.
def refinement_report(): # Compare identical native loading histories across actual mesh and increment refinements.
    names=['rebar_train_00','rebar_refine_mesh_all_output','rebar_refine_time'];reports={name:json.loads((OUT/'cases'/name/'receipt.json').read_text()) for name in names};base=reports[names[0]];rows=[] # Use the fixed initial representative as the common comparison.
    for name in names[1:]: # Compare physical response quantities without confusing node-count changes with full-field interpolation.
        other=reports[name];force=np.array([r.get('drive_force_N',np.nan) for r in other['checks']]);f0=np.array([r.get('drive_force_N',np.nan) for r in base['checks']]);p=np.array([r.get('max_peeq',np.nan) for r in other['checks']]);p0=np.array([r.get('max_peeq',np.nan) for r in base['checks']]);a=np.array([r.get('max_bond_slip_mm',np.nan) for r in other['checks']]);a0=np.array([r.get('max_bond_slip_mm',np.nan) for r in base['checks']]);rows.append({'case':name,'quality':other['row']['quality'],'force_path_relative_L2':float(np.linalg.norm(force-f0)/np.linalg.norm(f0)),'peak_peeq_relative_change':float(abs(p.max()-p0.max())/p.max()),'max_bond_slip_relative_change':float(abs(a.max()-a0.max())/a.max()),'max_full_weak_residual':max(r.get('full_weak_residual_yield_force_normalized',1.e30) for r in other['checks'])}) # Preserve local-field and integral-force convergence separately.
    report={'scope':'Same continuous declared interface law and geometry. Mesh refinement doubles embedded longitudinal cells, both transverse solid directions, and exposed-bar longitudinal cells. Time refinement halves maximum native continuation increments.','rows':rows,'mesh_gate':'force_path_relative_L2<0.05 and peak_peeq_relative_change<0.10','time_gate':'force_path_relative_L2<0.01 and peak_peeq_relative_change<0.02','status':'PASS' if rows[0]['force_path_relative_L2']<.05 and rows[0]['peak_peeq_relative_change']<.1 and rows[1]['force_path_relative_L2']<.01 and rows[1]['peak_peeq_relative_change']<.02 and all(r['quality']=='VALID_CONVERGED' for r in rows) else 'HOLD'};save(OUT/'verification/refinement.json',report);print(json.dumps(report,indent=2),flush=True);return report # Record coarse-mesh bias honestly without modifying field training results.
if __name__=='__main__': uniaxial_check() # Execute the registered independent material-law verification.
